if (internal_key.size() < 8) return false;
const char* ptr = internal_key.data() + internal_key.size() - 8;
uint64_t packed = std::bit_cast<uint64_t>(std::string_view(ptr, 8));
*sequence = packed & 0x7FFFFFFFFFFFFFFFULL;
*type = static_cast<uint8_t>(packed >> 56);
if (*type > 7) return false;
*user_key = Slice(internal_key.data(), internal_key.size() - 8);
return true;

